bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 60
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import pg from 'pg';import {readFileSync} from 'node:fs';
const e=process.env;
const db=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,database:e.VIDEOBOT_DB_NAME,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:5000});
try{
 const id=(await db.query("SELECT listing_id FROM videobot_post_receipts WHERE paid_message_id=$1",[4691])).rows[0]?.listing_id;
 if(!id)process.exitCode=61;
 else {
  const res=await db.query("SELECT kind,telegram_transaction_id,telegram_update_id,delivery_key,stars FROM videobot_stars_ledger WHERE listing_id=$1 ORDER BY recorded_at ASC",[id]);
  if(!res.rowCount)process.exitCode=62;
  else {
   const paid=res.rows.filter(r=>r.kind==='paid');
   if(!paid.length)process.exitCode=63;
   else if(paid.some(r=>typeof r.telegram_transaction_id!=='string'||!r.telegram_transaction_id||r.telegram_update_id==null))process.exitCode=71;
   else if(paid.some(r=>!Number.isFinite(Number(r.stars))||Number(r.stars)<=0))process.exitCode=72;
   else if(new Set(paid.map(r=>r.telegram_transaction_id)).size!==paid.length)process.exitCode=73;
   else {
    console.log('STARS_LEDGER_HAS_TRANSACTION_IDENTIFIERS=PASS');
    console.log('STARS_LEDGER_PURCHASE_COUNT='+paid.length);
    console.log('STARS_LEDGER_REFUND_COUNT='+res.rows.filter(r=>r.kind==='refunded').length);
    console.log('STARS_LEDGER_DELIVERY_VERSIONS='+new Set(paid.map(r=>r.delivery_key)).size);
   }
  }
 }
}catch(e){console.error('LEDGER_AUDIT_SQL_CODE='+String(e.code??'OTHER').slice(0,8));process.exitCode=79}finally{await db.end()}
JS
